local function sameName(a, b)
    local function normal(name)
        return (name or ""):lower():gsub("<[^>]*>", ""):gsub("[^%w]", "")
    end
    return normal(a) == normal(b)
end

local npcNames = {}
local npcLevels = {}
for _, record in ipairs(records) do
    local instanceID, name, minLevel, maxLevel, bosses, quests = unpack(record)
    local dungeon = C.dungeonKnowledge[name] or (C.raidKnowledge and C.raidKnowledge[name])
    if dungeon then
        dungeon.bosses = dungeon.bosses or {}
        dungeon.quests = dungeon.quests or {}
        if C.dungeonKnowledge[name] and minLevel > 0 and maxLevel > 0 then
            dungeon.level = minLevel .. "-" .. maxLevel
        end
        local refs = C.instanceDisplayRefs[instanceID]
        local metadata = C.bossMetadata[name] or {}
        C.bossMetadata[name] = metadata
        for _, fact in ipairs(bosses) do
            local bossName, level, rank, npcID, model, drops = unpack(fact)
            local boss
            for _, candidate in ipairs(dungeon.bosses) do
                if sameName(candidate.name, bossName) or (npcID > 0 and metadata[candidate.name] and metadata[candidate.name][3] == npcID) then
                    boss = candidate
                    break
                end
            end
            if not boss then
                boss = {name = bossName, loot = {}}
                dungeon.bosses[#dungeon.bosses + 1] = boss
            end
            boss.loot = boss.loot or {}
            local existingItems = {}
            for _, item in ipairs(boss.loot) do existingItems[item[1]] = item end
            for _, drop in ipairs(drops) do
                local item = existingItems[drop[1]]
                if not item then
                    item = {drop[1], "Item #" .. drop[1], ""}
                    boss.loot[#boss.loot + 1] = item
                    existingItems[drop[1]] = item
                end
                if drop[2] > 0 then item[5] = drop[2] end
            end
            if level > 0 then metadata[boss.name] = {level, rank, npcID} end
            if refs and model > 0 then refs.bosses[boss.name] = model end
            if npcID > 0 then npcNames[npcID] = boss.name; npcLevels[npcID] = level end
        end
        if #bosses > 0 then dungeon.preview = nil end
        local known = {}
        for _, quest in ipairs(dungeon.quests) do known[quest.id] = quest end
        for _, fact in ipairs(quests) do
            local id, xp, title, level, required, faction, money, items, choices, reputation = unpack(fact)
            local quest = known[id]
            if not quest and title then
                quest = {id = id, name = title, level = level, requires = required,
                    faction = faction == 1 and "Alliance" or faction == 2 and "Horde" or nil}
                if instanceID == 189 or instanceID == 429 or instanceID == 229 then
                    quest.complexWide = true
                end
                dungeon.quests[#dungeon.quests + 1] = quest
                known[id] = quest
            end
            if quest then
                if xp and xp > 0 then quest.liveXPFallback = xp end
                if money and money > 0 and not quest.rewardSummary then quest.rewardMoney = money end
                if reputation and #reputation > 0 and not quest.rewardSummary then quest.rewardReputation = reputation end
                if (not quest.rewardItems or #quest.rewardItems == 0) and ((items and #items > 0) or (choices and #choices > 0)) then
                    quest.rewardItems = {}
                    local rewardList = choices and #choices > 0 and choices or items
                    for _, itemID in ipairs(rewardList) do
                        quest.rewardItems[#quest.rewardItems + 1] = {itemID, "Item #" .. itemID}
                    end
                    quest.rewardChoice = choices and #choices > 0 or false
                end
            end
        end
    end
end

for floorID, pins in pairs(pinRecords) do
    local existing = C.mapBossPins[floorID] or {}
    C.mapBossPins[floorID] = existing
    local byNPC = {}
    for _, pin in ipairs(existing) do byNPC[pin[3]] = true end
    for _, pin in ipairs(pins) do
        if not byNPC[pin[3]] and npcNames[pin[3]] then
            existing[#existing + 1] = {pin[1], pin[2], pin[3], npcNames[pin[3]], npcLevels[pin[3]]}
            byNPC[pin[3]] = true
        end
    end
end
